{
  "name": "triage-worker-example",
  "private": true,
  "packageManager": "pnpm@11.15.0",
  "scripts": {
    "test": "node --test",
    "verify": "pnpm test"
  }
}

/**
 * Stable failure taxonomy shared by bootstrap, doctor, verify, and teardown.
 * The prefix names the owner, so an orchestrator can route without parsing prose.
 */

export const OWNER_RUNNER = 'runner';
export const OWNER_REPO = 'repo';
export const OWNER_INTERNAL = 'internal';

/** failure class -> { owner, retryable, recovery } */
export const FAILURE_CLASSES = {
  'runner/missing_task_identity': {
    owner: OWNER_RUNNER,
    retryable: false,
    recovery: 'Export AGENT_TASK_ID and AGENT_ATTEMPT_ID before dispatching the attempt.',
  },
  'runner/missing_identity': {
    owner: OWNER_RUNNER,
    retryable: false,
    recovery: 'Attach the scoped machine identity so INFISICAL_TOKEN, INFISICAL_API_URL, and INFISICAL_PROJECT_ID are exported.',
  },
  'runner/invalid_identity': {
    owner: OWNER_RUNNER,
    retryable: false,
    recovery: 'Point INFISICAL_API_URL at an https endpoint reachable from the workspace.',
  },
  'runner/invalid_result_type': {
    owner: OWNER_RUNNER,
    retryable: false,
    recovery: 'Set AGENT_RESULT_TYPE to implementation or qa during triage.',
  },
  'runner/invalid_submission_target': {
    owner: OWNER_RUNNER,
    retryable: false,
    recovery: 'Dispatch a submission target the result type allows; qa tasks submit a qa_report, never a pull_request.',
  },
  'runner/invalid_authority': {
    owner: OWNER_RUNNER,
    retryable: false,
    recovery: 'Grant merge authority only on implementation tasks, otherwise set AGENT_MERGE_AUTHORITY=none.',
  },
  'runner/missing_target_revision': {
    owner: OWNER_RUNNER,
    retryable: false,
    recovery: 'A qa task must declare AGENT_TARGET_REVISION (and AGENT_TARGET_BUILD when a prebuilt artifact is tested).',
  },
  'runner/toolchain_missing': {
    owner: OWNER_RUNNER,
    retryable: false,
    recovery: 'Provision the declared base toolchain on the runner image, then re-dispatch.',
  },
  'runner/workspace_not_writable': {
    owner: OWNER_RUNNER,
    retryable: true,
    recovery: 'Allocate a writable isolated workspace and artifact volume for the attempt.',
  },
  'runner/network_denied': {
    owner: OWNER_RUNNER,
    retryable: true,
    recovery: 'Allow the declared registry and secret-manager destinations in the egress policy.',
  },
  'repo/contract_violation': {
    owner: OWNER_REPO,
    retryable: false,
    recovery: 'Fix the repository lifecycle contract; the declared inputs and the code disagree.',
  },
  'repo/package_manager_mismatch': {
    owner: OWNER_REPO,
    retryable: false,
    recovery: 'Reconcile the packageManager pin in package.json with the activated pnpm version.',
  },
  'repo/missing_lockfile': {
    owner: OWNER_REPO,
    retryable: false,
    recovery: 'Commit pnpm-lock.yaml so installs are reproducible, or remove the declared dependencies.',
  },
  'repo/dependency_install_failed': {
    owner: OWNER_REPO,
    retryable: true,
    recovery: 'Inspect the install log in the attempt artifact directory; a drifted lockfile needs a repository change.',
  },
  'repo/verification_failed': {
    owner: OWNER_REPO,
    retryable: false,
    recovery: 'Read logs/verify.log in the attempt artifact directory and fix the failing behaviour.',
  },
  'repo/verification_timeout': {
    owner: OWNER_REPO,
    retryable: true,
    recovery: 'Verification exceeded its bound; shorten the gate or raise AGENT_VERIFY_TIMEOUT_SECONDS deliberately.',
  },
  'repo/evidence_missing': {
    owner: OWNER_REPO,
    retryable: false,
    recovery: 'Capture the declared qa evidence and describe it in scenarios.json before submitting a report.',
  },
  'repo/evidence_invalid': {
    owner: OWNER_REPO,
    retryable: false,
    recovery: 'Correct scenarios.json against the schema in docs/automation.md.',
  },
  'repo/secret_exposure': {
    owner: OWNER_REPO,
    retryable: false,
    recovery: 'Redact the captured evidence; an injected secret value reached an artifact. Values are never printed.',
  },
  'repo/teardown_failed': {
    owner: OWNER_REPO,
    retryable: true,
    recovery: 'An owned runtime resource survived teardown; inspect teardown.json and release it before reuse.',
  },
  'repo/unreleasable_resource': {
    owner: OWNER_REPO,
    retryable: false,
    recovery: 'Record release and verify argv on ledger kinds this repository has no built-in handler for.',
  },
  'internal/unknown': {
    owner: OWNER_INTERNAL,
    retryable: true,
    recovery: 'Unclassified failure; inspect the attempt artifact directory.',
  },
};

/** Process exit codes, stable across all four entrypoints. */
export const EXIT = {
  ok: 0,
  repository: 1,
  runner: 2,
  /** ordinary work succeeded but cleanup or absence verification did not */
  teardown: 3,
};

export class LifecycleError extends Error {
  constructor(failureClass, message, { context = {}, cause } = {}) {
    super(message, { cause });
    this.name = 'LifecycleError';
    this.failureClass = FAILURE_CLASSES[failureClass] ? failureClass : 'internal/unknown';
    this.context = context;
  }

  get owner() {
    return FAILURE_CLASSES[this.failureClass].owner;
  }

  get retryable() {
    return FAILURE_CLASSES[this.failureClass].retryable;
  }

  get recovery() {
    return FAILURE_CLASSES[this.failureClass].recovery;
  }

  get exitCode() {
    if (this.failureClass === 'repo/teardown_failed') return EXIT.teardown;
    return this.owner === OWNER_RUNNER ? EXIT.runner : EXIT.repository;
  }

  toJSON() {
    return {
      failure_class: this.failureClass,
      owner: this.owner,
      retryable: this.retryable,
      message: this.message,
      recovery: this.recovery,
      context: this.context,
    };
  }
}

export function classify(error) {
  if (error instanceof LifecycleError) return error;
  return new LifecycleError('internal/unknown', error?.message ?? String(error), { cause: error });
}

/**
 * Writes one actionable block to stderr. Context values must already be
 * non-secret; callers pass names and counts, never injected values.
 */
export function printFailure(stage, error) {
  const failure = classify(error);
  const lines = [
    `${stage} failed`,
    `  failure_class: ${failure.failureClass}`,
    `  owner:         ${failure.owner}`,
    `  retryable:     ${failure.retryable}`,
    `  detail:        ${failure.message}`,
    `  recovery:      ${failure.recovery}`,
  ];
  for (const [key, value] of Object.entries(failure.context)) {
    lines.push(`  ${key}: ${typeof value === 'object' ? JSON.stringify(value) : value}`);
  }
  process.stderr.write(`${lines.join('\n')}\n`);
  return failure;
}

/** Single structured line so a log collector can route without parsing prose. */
export function printEvent(event) {
  process.stdout.write(`${JSON.stringify({ ...event, ts: new Date().toISOString() })}\n`);
}

/**
 * Runner contract: the environment an orchestrator must supply, parsed once into
 * a validated shape the lifecycle entrypoints use internally.
 *
 * Nothing here reads a secret's value. Identity variables are checked for
 * presence and shape only.
 */

import { LifecycleError } from './failure.mjs';

export const RESULT_TYPES = ['implementation', 'qa'];

/** Submission targets each result type is allowed to reach. */
export const ALLOWED_TARGETS = {
  implementation: ['pull_request', 'none'],
  qa: ['qa_report', 'none'],
};

export const DEFAULT_TARGET = {
  implementation: 'pull_request',
  qa: 'qa_report',
};

export const MERGE_AUTHORITIES = ['none', 'merge'];

/** Injected by the runner's machine identity. Presence is required, values are never read. */
export const IDENTITY_VARS = ['INFISICAL_TOKEN', 'INFISICAL_API_URL', 'INFISICAL_PROJECT_ID'];

/** Non-secret of the three above; safe to echo. */
export const NON_SECRET_IDENTITY_VARS = ['INFISICAL_API_URL', 'INFISICAL_PROJECT_ID'];

/** Path-safe identifiers: keeps artifact directories inside the workspace. */
const IDENTIFIER = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;

const DEFAULTS = {
  verifyTimeoutSeconds: 900,
  retryBudget: 2,
  baseRef: 'main',
  artifactRoot: 'artifacts',
};

function required(env, name, failureClass) {
  const value = env[name];
  if (typeof value !== 'string' || value.trim() === '') {
    throw new LifecycleError(failureClass, `${name} is not set`, { missing: name });
  }
  return value.trim();
}

function identifier(env, name, failureClass) {
  const value = required(env, name, failureClass);
  if (!IDENTIFIER.test(value)) {
    throw new LifecycleError(
      failureClass,
      `${name} must match ${IDENTIFIER.source} so artifact paths stay inside the workspace`,
      { variable: name, length: value.length },
    );
  }
  return value;
}

function positiveInteger(env, name, fallback) {
  const raw = env[name];
  if (raw === undefined || raw === '') return fallback;
  const parsed = Number(raw);
  if (!Number.isInteger(parsed) || parsed < 0) {
    throw new LifecycleError('runner/invalid_result_type', `${name} must be a non-negative integer`, {
      variable: name,
    });
  }
  return parsed;
}

/**
 * @param {Record<string, string | undefined>} env
 * @returns {{
 *   taskId: string, attemptId: string, attemptNumber: number, retryBudget: number,
 *   resultType: 'implementation'|'qa', submissionTarget: string, mergeAuthority: string,
 *   baseRef: string|null, targetRevision: string|null, targetBuild: string|null,
 *   environmentName: string, runner: string, verifyTimeoutSeconds: number,
 *   artifactDir: string, identity: { apiUrl: string, projectId: string, tokenPresent: true }
 * }}
 */
export function parseRunnerContract(env) {
  const taskId = identifier(env, 'AGENT_TASK_ID', 'runner/missing_task_identity');
  const attemptId = identifier(env, 'AGENT_ATTEMPT_ID', 'runner/missing_task_identity');

  const resultType = required(env, 'AGENT_RESULT_TYPE', 'runner/invalid_result_type');
  if (!RESULT_TYPES.includes(resultType)) {
    throw new LifecycleError(
      'runner/invalid_result_type',
      `AGENT_RESULT_TYPE must be one of ${RESULT_TYPES.join(', ')}`,
      { received: resultType },
    );
  }

  const submissionTarget = (env.AGENT_SUBMISSION_TARGET ?? DEFAULT_TARGET[resultType]).trim();
  if (!ALLOWED_TARGETS[resultType].includes(submissionTarget)) {
    throw new LifecycleError(
      'runner/invalid_submission_target',
      `result type ${resultType} may only submit to ${ALLOWED_TARGETS[resultType].join(' or ')}`,
      { result_type: resultType, requested_target: submissionTarget },
    );
  }

  const mergeAuthority = (env.AGENT_MERGE_AUTHORITY ?? 'none').trim();
  if (!MERGE_AUTHORITIES.includes(mergeAuthority)) {
    throw new LifecycleError(
      'runner/invalid_authority',
      `AGENT_MERGE_AUTHORITY must be one of ${MERGE_AUTHORITIES.join(', ')}`,
      { received: mergeAuthority },
    );
  }
  if (mergeAuthority === 'merge' && resultType !== 'implementation') {
    throw new LifecycleError(
      'runner/invalid_authority',
      'merge authority is only grantable on implementation tasks',
      { result_type: resultType },
    );
  }

  for (const name of IDENTITY_VARS) {
    required(env, name, 'runner/missing_identity');
  }
  const apiUrl = env.INFISICAL_API_URL.trim();
  let parsedUrl;
  try {
    parsedUrl = new URL(apiUrl);
  } catch {
    throw new LifecycleError('runner/invalid_identity', 'INFISICAL_API_URL is not a URL', {
      variable: 'INFISICAL_API_URL',
    });
  }
  if (parsedUrl.protocol !== 'https:') {
    throw new LifecycleError('runner/invalid_identity', 'INFISICAL_API_URL must use https', {
      protocol: parsedUrl.protocol,
    });
  }

  let targetRevision = env.AGENT_TARGET_REVISION?.trim() || null;
  if (resultType === 'qa' && !targetRevision) {
    throw new LifecycleError(
      'runner/missing_target_revision',
      'a qa task must declare the revision under test',
      { variable: 'AGENT_TARGET_REVISION' },
    );
  }

  const artifactRoot = env.AGENT_ARTIFACT_ROOT?.trim() || DEFAULTS.artifactRoot;

  return {
    taskId,
    attemptId,
    attemptNumber: positiveInteger(env, 'AGENT_ATTEMPT_NUMBER', 1) || 1,
    retryBudget: positiveInteger(env, 'AGENT_RETRY_BUDGET', DEFAULTS.retryBudget),
    resultType,
    submissionTarget,
    mergeAuthority,
    baseRef: resultType === 'implementation' ? env.AGENT_BASE_REF?.trim() || DEFAULTS.baseRef : null,
    targetRevision,
    targetBuild: env.AGENT_TARGET_BUILD?.trim() || null,
    environmentName: env.AGENT_ENVIRONMENT?.trim() || 'devbox',
    runner: env.AGENT_RUNNER?.trim() || 'unknown',
    verifyTimeoutSeconds:
      positiveInteger(env, 'AGENT_VERIFY_TIMEOUT_SECONDS', DEFAULTS.verifyTimeoutSeconds) ||
      DEFAULTS.verifyTimeoutSeconds,
    artifactDir: `${artifactRoot}/${taskId}/${attemptId}`,
    identity: {
      apiUrl,
      projectId: env.INFISICAL_PROJECT_ID.trim(),
      tokenPresent: true,
    },
  };
}

/**
 * Branch name an implementation attempt is allowed to push. QA attempts get
 * null: they must not manufacture a ref.
 */
export function allowedBranch(contract) {
  if (contract.resultType !== 'implementation') return null;
  return `agent/${contract.taskId}/${contract.attemptId}`;
}

/**
 * Literal values that must never appear in a preserved artifact. Collected by
 * name pattern so an added secret is covered without editing this list.
 */
export function secretValues(env) {
  const pattern = /(TOKEN|SECRET|PASSWORD|PASSPHRASE|CREDENTIAL|PRIVATE_KEY|_KEY$|API_KEY)/i;
  const values = new Set();
  for (const [name, value] of Object.entries(env)) {
    if (typeof value !== 'string' || value.length < 8) continue;
    if (NON_SECRET_IDENTITY_VARS.includes(name)) continue;
    if (pattern.test(name)) values.add(value);
  }
  return [...values];
}

/**
 * Ownership ledger for runtime resources an attempt raises.
 *
 * Rules this module enforces:
 *  - only resources recorded by this attempt are released
 *  - resources present in the pre-existing snapshot are never released
 *  - release happens by recorded id or owned process group, never by name
 *  - absence is verified after release; cleanup exit status is not trusted
 */

import { appendFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import { spawnSync } from 'node:child_process';

import { LifecycleError } from './failure.mjs';

export const RESOURCE_KINDS = [
  'process',
  'process_group',
  'container',
  'simulator',
  'emulator',
  'vm',
  'service',
  'temp_dir',
];

/** Which stage raised the resource; teardown scopes releases by this. */
export const SCOPES = ['bootstrap', 'verify', 'attempt'];

const SIGNAL_GRACE_MS = 5000;
const COMMAND_TIMEOUT_MS = 60_000;

function run(argv, { timeout = COMMAND_TIMEOUT_MS } = {}) {
  const [command, ...args] = argv;
  const result = spawnSync(command, args, { encoding: 'utf8', timeout });
  return {
    status: result.status,
    stdout: (result.stdout ?? '').trim(),
    stderr: (result.stderr ?? '').trim(),
    spawnError: result.error ? result.error.code ?? result.error.message : null,
  };
}

function has(command) {
  return run(['/usr/bin/env', 'which', command], { timeout: 5000 }).status === 0;
}

function sleepMs(ms) {
  // Bounded synchronous wait; teardown must not depend on an event loop turn.
  const shared = new SharedArrayBuffer(4);
  Atomics.wait(new Int32Array(shared), 0, 0, ms);
}

/**
 * @param {object} entry
 * @returns {object} normalised ledger entry
 */
export function normaliseEntry(entry) {
  if (!RESOURCE_KINDS.includes(entry.kind)) {
    throw new LifecycleError('repo/unreleasable_resource', `unknown resource kind: ${entry.kind}`, {
      known_kinds: RESOURCE_KINDS,
    });
  }
  if (entry.id === undefined || String(entry.id).trim() === '') {
    throw new LifecycleError('repo/unreleasable_resource', 'a ledger entry needs an exact resource id', {
      kind: entry.kind,
    });
  }
  const scope = entry.scope ?? 'attempt';
  if (!SCOPES.includes(scope)) {
    throw new LifecycleError('repo/unreleasable_resource', `unknown scope: ${scope}`, { known_scopes: SCOPES });
  }
  const needsCustom = ['emulator', 'vm', 'service'].includes(entry.kind);
  if (needsCustom && !Array.isArray(entry.release)) {
    throw new LifecycleError(
      'repo/unreleasable_resource',
      `kind ${entry.kind} has no built-in handler; record release (and verify) argv with it`,
      { kind: entry.kind },
    );
  }
  return {
    kind: entry.kind,
    id: String(entry.id),
    pgid: entry.pgid ?? null,
    label: entry.label ?? null,
    scope,
    runtime: entry.runtime ?? (entry.kind === 'container' ? 'docker' : null),
    release: Array.isArray(entry.release) ? entry.release : null,
    verify: Array.isArray(entry.verify) ? entry.verify : null,
    pre_existing: entry.pre_existing === true,
    acquired_at: entry.acquired_at ?? new Date().toISOString(),
    released_at: entry.released_at ?? null,
  };
}

export function recordResource(ledgerPath, entry) {
  const normalised = normaliseEntry(entry);
  mkdirSync(dirname(ledgerPath), { recursive: true });
  appendFileSync(ledgerPath, `${JSON.stringify(normalised)}\n`, 'utf8');
  return normalised;
}

export function readLedger(ledgerPath) {
  if (!existsSync(ledgerPath)) return [];
  return readFileSync(ledgerPath, 'utf8')
    .split('\n')
    .filter((line) => line.trim() !== '')
    .map((line) => JSON.parse(line));
}

/**
 * Latest state per (kind, id): a released entry supersedes its acquisition, which
 * makes teardown idempotent across retries.
 */
export function currentOwnership(entries) {
  const byKey = new Map();
  for (const entry of entries) {
    byKey.set(`${entry.kind}:${entry.id}`, { ...(byKey.get(`${entry.kind}:${entry.id}`) ?? {}), ...entry });
  }
  return [...byKey.values()];
}

/**
 * Resources this attempt must release: recorded, not pre-existing, not already
 * released, and in scope.
 */
export function releasable(entries, { scope = 'attempt', preexisting = [] } = {}) {
  const preexistingKeys = new Set(preexisting.map((item) => `${item.kind}:${item.id}`));
  return currentOwnership(entries).filter((entry) => {
    if (entry.pre_existing) return false;
    if (preexistingKeys.has(`${entry.kind}:${entry.id}`)) return false;
    if (entry.released_at) return false;
    if (scope !== 'attempt' && entry.scope !== scope) return false;
    return true;
  });
}

function releaseProcess(entry) {
  const target = entry.kind === 'process_group' ? -Number(entry.pgid ?? entry.id) : Number(entry.id);
  for (const signal of ['SIGTERM', 'SIGKILL']) {
    try {
      process.kill(target, signal);
    } catch (error) {
      if (error.code === 'ESRCH') return { status: 0, note: 'already gone' };
      if (error.code === 'EPERM') {
        return { status: 1, note: 'not permitted; the attempt does not own this process' };
      }
      throw error;
    }
    sleepMs(SIGNAL_GRACE_MS);
    if (!processAlive(target)) return { status: 0, note: `released with ${signal}` };
  }
  return { status: 1, note: 'survived SIGKILL' };
}

function processAlive(target) {
  try {
    process.kill(target, 0);
    return true;
  } catch (error) {
    return error.code === 'EPERM';
  }
}

function releaseContainer(entry) {
  const runtime = entry.runtime ?? 'docker';
  if (!has(runtime)) return { status: 1, note: `${runtime} is not on PATH` };
  const stopped = run([runtime, 'stop', entry.id]);
  return { status: stopped.status === 0 ? 0 : 1, note: stopped.stderr || stopped.stdout || 'stop issued' };
}

function containerRunning(entry) {
  const runtime = entry.runtime ?? 'docker';
  if (!has(runtime)) return false;
  const inspected = run([runtime, 'inspect', '-f', '{{.State.Running}}', entry.id]);
  return inspected.status === 0 && inspected.stdout === 'true';
}

function releaseSimulator(entry) {
  if (!has('xcrun')) return { status: 1, note: 'xcrun is not on PATH' };
  const shutdown = run(['xcrun', 'simctl', 'shutdown', entry.id]);
  const gone = shutdown.status === 0 || /current state: Shutdown/i.test(shutdown.stderr);
  return { status: gone ? 0 : 1, note: shutdown.stderr || 'shutdown issued' };
}

function simulatorBooted(entry) {
  if (!has('xcrun')) return false;
  const listed = run(['xcrun', 'simctl', 'list', 'devices', 'booted']);
  return listed.status === 0 && listed.stdout.includes(entry.id);
}

function releaseTempDir(entry) {
  const { rmSync } = require('node:fs');
  rmSync(entry.id, { recursive: true, force: true });
  return { status: 0, note: 'removed' };
}

/** Release one entry. Returns a machine-readable outcome; never throws for a live resource. */
export function releaseEntry(entry) {
  const started = new Date().toISOString();
  let outcome;
  try {
    if (entry.release) {
      const result = run(entry.release);
      outcome = { status: result.status === 0 ? 0 : 1, note: result.stderr || result.spawnError || 'custom release' };
    } else if (entry.kind === 'process' || entry.kind === 'process_group') {
      outcome = releaseProcess(entry);
    } else if (entry.kind === 'container') {
      outcome = releaseContainer(entry);
    } else if (entry.kind === 'simulator') {
      outcome = releaseSimulator(entry);
    } else if (entry.kind === 'temp_dir') {
      outcome = releaseTempDir(entry);
    } else {
      outcome = { status: 1, note: 'no handler and no recorded release argv' };
    }
  } catch (error) {
    outcome = { status: 1, note: error.code ?? error.message };
  }
  const absent = verifyAbsent(entry);
  return {
    kind: entry.kind,
    id: entry.id,
    label: entry.label,
    scope: entry.scope,
    release_status: outcome.status,
    note: outcome.note,
    absent,
    released_at: absent ? new Date().toISOString() : null,
    attempted_at: started,
  };
}

/** Read-only absence check. Trusted over the release command's exit status. */
export function verifyAbsent(entry) {
  if (entry.verify) return run(entry.verify).status === 0;
  switch (entry.kind) {
    case 'process':
      return !processAlive(Number(entry.id));
    case 'process_group':
      return !processAlive(-Number(entry.pgid ?? entry.id));
    case 'container':
      return !containerRunning(entry);
    case 'simulator':
      return !simulatorBooted(entry);
    case 'temp_dir':
      return !existsSync(entry.id);
    default:
      return false;
  }
}

/**
 * Snapshot of resources already running before the attempt touched anything.
 * Only kinds this repository can enumerate cheaply are recorded; the snapshot is
 * a preservation guard, not an inventory.
 */
export function snapshotPreexisting() {
  const items = [];
  if (has('docker')) {
    const listed = run(['docker', 'ps', '-q']);
    if (listed.status === 0) {
      for (const id of listed.stdout.split('\n').filter(Boolean)) {
        items.push({ kind: 'container', id, runtime: 'docker' });
      }
    }
  }
  if (has('xcrun')) {
    const listed = run(['xcrun', 'simctl', 'list', 'devices', 'booted']);
    if (listed.status === 0) {
      for (const match of listed.stdout.matchAll(/\(([0-9A-F-]{36})\)/g)) {
        items.push({ kind: 'simulator', id: match[1] });
      }
    }
  }
  return { captured_at: new Date().toISOString(), items };
}

export function writeSnapshot(path, snapshot) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, `${JSON.stringify(snapshot, null, 2)}\n`, 'utf8');
}

export function readSnapshot(path) {
  if (!existsSync(path)) return { captured_at: null, items: [] };
  return JSON.parse(readFileSync(path, 'utf8'));
}

/**
 * Confirms pre-existing resources are still present. A preserved resource that
 * vanished means teardown reached past its ownership boundary.
 */
export function verifyPreservation(snapshot) {
  return snapshot.items
    .map((item) => ({ ...item, still_present: !verifyAbsent(normaliseEntry({ ...item, pre_existing: true })) }))
    .filter((item) => !item.still_present);
}

