#!/usr/bin/env node
/**
 * `pnpm verify` — the canonical bounded gate, reused by humans, agents, and CI.
 *
 * It still runs the repository's own test gate (`pnpm test`). On top of that it
 * records inspectable outcome evidence and a machine-readable manifest under
 * artifacts/<task>/<attempt>/, scans preserved text evidence for injected secret
 * values, and releases the process tree it raised on every exit path.
 *
 * Result paths:
 *  - implementation: the repository gate is mandatory; failure exits non-zero.
 *  - qa: scenarios.json plus its referenced evidence is mandatory; the repository
 *    gate is optional because the revision or build under test may be prebuilt.
 *    A failing scenario is a finding, not a broken attempt, so it does not fail
 *    the command unless AGENT_QA_FAIL_ON_SCENARIO_FAILURE=1.
 */

import { createWriteStream, existsSync } from 'node:fs';
import { spawn } from 'node:child_process';
import { join, relative } from 'node:path';

import { EXIT, LifecycleError, classify, printEvent, printFailure } from './failure.mjs';
import { allowedBranch, parseRunnerContract, secretValues } from './contract.mjs';
import {
  MANIFEST_SCHEMA,
  REDACTION,
  artifactPaths,
  classifyFormat,
  describeArtifacts,
  describeEnvironment,
  describeRevision,
  ensureArtifactDirs,
  listArtifactFiles,
  readScenarios,
  scanForSecrets,
  writeManifest,
} from './artifacts.mjs';
import { recordResource, snapshotPreexisting, writeSnapshot } from './resources.mjs';
import { runTeardown } from './teardown.mjs';

const repoRoot = process.cwd();
const GATE_COMMAND = ['pnpm', 'test'];

/**
 * Runs the repository gate as an owned process group so a launcher's descendants
 * are released together, bounded by AGENT_VERIFY_TIMEOUT_SECONDS.
 */
function runGate({ contract, paths }) {
  return new Promise((resolve) => {
    const logPath = join(paths.logs, 'verify.log');
    const log = createWriteStream(logPath, { flags: 'w' });
    const startedAt = new Date().toISOString();
    const [command, ...args] = GATE_COMMAND;
    const child = spawn(command, args, { cwd: repoRoot, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });

    if (child.pid) {
      recordResource(paths.ledger, {
        kind: 'process_group',
        id: String(child.pid),
        pgid: child.pid,
        label: GATE_COMMAND.join(' '),
        scope: 'verify',
      });
    }

    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      try {
        process.kill(-child.pid, 'SIGTERM');
      } catch {
        /* teardown re-checks and escalates */
      }
    }, contract.verifyTimeoutSeconds * 1000);

    for (const stream of [child.stdout, child.stderr]) {
      stream.on('data', (chunk) => {
        log.write(chunk);
        process.stdout.write(chunk);
      });
    }

    child.on('error', (error) => {
      clearTimeout(timer);
      log.end(`\nspawn error: ${error.code ?? error.message}\n`);
      resolve({ command: GATE_COMMAND.join(' '), exitCode: 127, timedOut: false, log: logPath, startedAt, spawnError: error.code ?? error.message });
    });

    child.on('close', (code, signal) => {
      clearTimeout(timer);
      log.end();
      resolve({
        command: GATE_COMMAND.join(' '),
        exitCode: code === null ? 124 : code,
        signal: signal ?? null,
        timedOut,
        log: relative(paths.root, logPath),
        startedAt,
        finishedAt: new Date().toISOString(),
      });
    });
  });
}

function summariseScenarios(scenarios) {
  const summary = { passed: 0, failed: 0, blocked: 0, skipped: 0 };
  for (const scenario of scenarios) summary[scenario.result] += 1;
  return summary;
}

function gateScenario(gate) {
  return {
    id: 'repository-gate',
    description: `${gate.command} on the checked-out revision`,
    result: gate.exitCode === 0 ? 'passed' : 'failed',
    producer: gate.command,
    started_at: gate.startedAt,
    finished_at: gate.finishedAt ?? null,
    evidence: [gate.log].filter(Boolean),
  };
}

async function main() {
  const startedAt = new Date().toISOString();
  const contract = parseRunnerContract(process.env);
  const paths = ensureArtifactDirs(artifactPaths(contract, repoRoot));

  if (!existsSync(paths.snapshot)) writeSnapshot(paths.snapshot, snapshotPreexisting());

  // Cleanup is registered before the first failure point below.
  let tornDown = false;
  const cleanup = (reason, primaryStatus) => {
    if (tornDown) return { exitCode: primaryStatus, clean: true };
    tornDown = true;
    return runTeardown({ contract, paths, scope: 'verify', reason, primaryStatus });
  };
  for (const signal of ['SIGINT', 'SIGTERM', 'SIGHUP']) {
    process.on(signal, () => {
      cleanup('cancelled', 130);
      process.exit(130);
    });
  }

  const runGateForQa = contract.resultType === 'implementation' || process.env.AGENT_QA_RUN_REPOSITORY_GATE === '1';
  const gate = runGateForQa ? await runGate({ contract, paths }) : null;

  let failure = null;
  const scenarios = [];
  let scenarioByPath = new Map();
  let declaredScenarios = null;

  if (gate) scenarios.push(gateScenario(gate));

  if (gate && gate.timedOut) {
    failure = new LifecycleError('repo/verification_timeout', `the gate exceeded ${contract.verifyTimeoutSeconds}s`, {
      command: gate.command,
      log: gate.log,
    });
  } else if (gate && gate.exitCode !== 0 && contract.resultType === 'implementation') {
    failure = new LifecycleError('repo/verification_failed', `${gate.command} exited ${gate.exitCode}`, {
      exit_code: gate.exitCode,
      log: gate.log,
    });
  }

  if (contract.resultType === 'qa') {
    try {
      const read = readScenarios(paths);
      declaredScenarios = read.declared;
      scenarioByPath = read.scenarioByPath;
      scenarios.push(...read.declared.scenarios);
    } catch (error) {
      failure ??= classify(error);
    }
  }

  const summary = summariseScenarios(scenarios);
  const files = listArtifactFiles(paths);
  const scan = scanForSecrets(paths.root, files, secretValues(process.env));
  const exposed = new Set(scan.findings.map((finding) => finding.path));
  if (scan.findings.length > 0) {
    failure = new LifecycleError('repo/secret_exposure', 'an injected secret value appears in preserved evidence', {
      affected_artifacts: scan.findings.map((finding) => finding.path),
    });
  }

  const qaScenarioFailure =
    contract.resultType === 'qa' &&
    process.env.AGENT_QA_FAIL_ON_SCENARIO_FAILURE === '1' &&
    summary.failed + summary.blocked > 0;
  if (qaScenarioFailure && !failure) {
    failure = new LifecycleError('repo/verification_failed', 'a declared qa scenario failed', {
      failed: summary.failed,
      blocked: summary.blocked,
    });
  }

  const manifest = {
    schema: MANIFEST_SCHEMA,
    task_id: contract.taskId,
    attempt_id: contract.attemptId,
    attempt_number: contract.attemptNumber,
    retry_budget: contract.retryBudget,
    result_type: contract.resultType,
    submission_target: contract.submissionTarget,
    merge_authority: contract.mergeAuthority,
    allowed_branch: allowedBranch(contract),
    revision: describeRevision(repoRoot, contract),
    build: { id: contract.targetBuild, source: contract.targetBuild ? 'runner' : null },
    environment: describeEnvironment(contract, repoRoot),
    started_at: startedAt,
    finished_at: new Date().toISOString(),
    outcome: failure ? 'failed' : 'passed',
    failure_class: failure?.failureClass ?? null,
    retryable: failure ? failure.retryable : false,
    recovery: failure?.recovery ?? null,
    gate,
    scenario_summary: summary,
    scenarios,
    findings_present: summary.failed + summary.blocked > 0,
    qa_report: declaredScenarios
      ? { title: declaredScenarios.title ?? null, notes: declaredScenarios.notes ?? null }
      : null,
    redaction: { ...scan, status: scan.findings.length === 0 ? 'clean' : 'secret-detected' },
    artifacts: describeArtifacts(paths, {
      producer: 'pnpm verify',
      scenarioByPath,
      redactionFor: (rel) =>
        exposed.has(rel) ? REDACTION.exposed : classifyFormat(rel).text ? REDACTION.clean : REDACTION.unscanned,
    }),
  };
  writeManifest(paths, manifest);

  const primaryStatus = failure ? failure.exitCode : EXIT.ok;
  printEvent({
    event: 'lifecycle.verify',
    operation: 'verify',
    resource_id: `${contract.taskId}/${contract.attemptId}`,
    outcome: manifest.outcome,
    error_kind: manifest.failure_class,
    result_type: contract.resultType,
    scenarios: summary,
    manifest: relative(repoRoot, paths.manifest),
  });
  if (failure) printFailure('verify', failure);

  const teardown = cleanup(failure ? 'failure' : 'success', primaryStatus);
  if (!teardown.clean) {
    printFailure(
      'verify teardown',
      new LifecycleError('repo/teardown_failed', 'the gate process tree survived teardown', {
        record: relative(repoRoot, paths.teardown),
      }),
    );
  }
  return teardown.exitCode;
}

main()
  .then((code) => process.exit(code))
  .catch((error) => {
    const failure = printFailure('verify', error);
    printEvent({
      event: 'lifecycle.verify',
      operation: 'verify',
      resource_id: `${process.env.AGENT_TASK_ID ?? 'unknown'}/${process.env.AGENT_ATTEMPT_ID ?? 'unknown'}`,
      outcome: 'failed',
      error_kind: failure.failureClass,
      retryable: failure.retryable,
    });
    process.exit(failure.exitCode);
  });

#!/usr/bin/env node
/**
 * `pnpm own` — register a runtime resource this attempt raised, so teardown can
 * release exactly it and nothing else.
 *
 *   pnpm own record --kind process_group --id 4321 --label dev-server
 *   pnpm own record --kind container --id 9ab3f1 --runtime docker
 *   pnpm own record --kind vm --id builder-1 \
 *     --release '["vmctl","stop","builder-1"]' --verify '["vmctl","is-stopped","builder-1"]'
 *   pnpm own list
 *
 * A persistent resource must be recorded before it is driven. Anything not in the
 * ledger is treated as pre-existing and is preserved.
 */

import { EXIT, LifecycleError, printEvent, printFailure } from './failure.mjs';
import { parseRunnerContract } from './contract.mjs';
import { artifactPaths, ensureArtifactDirs } from './artifacts.mjs';
import { RESOURCE_KINDS, readLedger, recordResource, releasable, readSnapshot } from './resources.mjs';

const FLAGS = ['--kind', '--id', '--pgid', '--label', '--scope', '--runtime', '--release', '--verify'];

function parseArgs(argv) {
  const options = {};
  for (let index = 0; index < argv.length; index += 1) {
    const [flag, inline] = argv[index].split('=');
    if (!FLAGS.includes(flag)) {
      throw new LifecycleError('repo/contract_violation', `unknown flag: ${flag}`, { known_flags: FLAGS });
    }
    const value = inline ?? argv[index + 1];
    if (inline === undefined) index += 1;
    if (value === undefined) {
      throw new LifecycleError('repo/contract_violation', `${flag} needs a value`, {});
    }
    options[flag.slice(2)] = value;
  }
  return options;
}

function jsonArgv(raw, flag) {
  if (raw === undefined) return undefined;
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new LifecycleError('repo/contract_violation', `${flag} must be a JSON array of argv strings`, {});
  }
  if (!Array.isArray(parsed) || parsed.some((item) => typeof item !== 'string')) {
    throw new LifecycleError('repo/contract_violation', `${flag} must be a JSON array of argv strings`, {});
  }
  return parsed;
}

function main() {
  const [subcommand, ...rest] = process.argv.slice(2);
  const contract = parseRunnerContract(process.env);
  const paths = ensureArtifactDirs(artifactPaths(contract, process.cwd()));

  if (subcommand === 'list') {
    const outstanding = releasable(readLedger(paths.ledger), { preexisting: readSnapshot(paths.snapshot).items });
    process.stdout.write(`${JSON.stringify({ outstanding }, null, 2)}\n`);
    return EXIT.ok;
  }

  if (subcommand !== 'record') {
    throw new LifecycleError('repo/contract_violation', 'usage: pnpm own record --kind <kind> --id <id> | pnpm own list', {
      known_kinds: RESOURCE_KINDS,
    });
  }

  const options = parseArgs(rest);
  const entry = recordResource(paths.ledger, {
    kind: options.kind,
    id: options.id,
    pgid: options.pgid ? Number(options.pgid) : null,
    label: options.label ?? null,
    scope: options.scope ?? 'attempt',
    runtime: options.runtime,
    release: jsonArgv(options.release, '--release'),
    verify: jsonArgv(options.verify, '--verify'),
  });
  printEvent({
    event: 'lifecycle.resource_recorded',
    operation: 'own.record',
    resource_id: `${entry.kind}:${entry.id}`,
    outcome: 'recorded',
    error_kind: null,
    scope: entry.scope,
    teardown: 'pnpm teardown',
  });
  return EXIT.ok;
}

try {
  process.exit(main());
} catch (error) {
  const failure = printFailure('own', error);
  process.exit(failure.exitCode);
}

{
  "name": "triage-worker-example",
  "private": true,
  "packageManager": "pnpm@11.15.0",
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "bootstrap": "node scripts/lifecycle/bootstrap.mjs",
    "doctor": "node scripts/lifecycle/doctor.mjs",
    "test": "node --test test/",
    "verify": "node scripts/lifecycle/verify.mjs",
    "teardown": "node scripts/lifecycle/teardown.mjs",
    "own": "node scripts/lifecycle/own.mjs"
  }
}

import assert from 'node:assert/strict';
import test from 'node:test';

import { allowedBranch, parseRunnerContract, secretValues } from '../scripts/lifecycle/contract.mjs';

const IDENTITY = {
  INFISICAL_TOKEN: 'st.machine.aaaaaaaaaaaaaaaa',
  INFISICAL_API_URL: 'https://secrets.example.com',
  INFISICAL_PROJECT_ID: 'proj_1234',
};

const IMPLEMENTATION = {
  ...IDENTITY,
  AGENT_TASK_ID: 'task-123',
  AGENT_ATTEMPT_ID: 'attempt-1',
  AGENT_RESULT_TYPE: 'implementation',
};

const QA = {
  ...IDENTITY,
  AGENT_TASK_ID: 'task-123',
  AGENT_ATTEMPT_ID: 'attempt-1',
  AGENT_RESULT_TYPE: 'qa',
  AGENT_TARGET_REVISION: 'deadbeef',
};

function failsWith(env, failureClass) {
  try {
    parseRunnerContract(env);
  } catch (error) {
    assert.equal(error.failureClass, failureClass);
    return error;
  }
  assert.fail(`expected ${failureClass}`);
}

test('implementation defaults to a pull request, no merge authority, main base', () => {
  const contract = parseRunnerContract(IMPLEMENTATION);
  assert.equal(contract.submissionTarget, 'pull_request');
  assert.equal(contract.mergeAuthority, 'none');
  assert.equal(contract.baseRef, 'main');
  assert.equal(contract.artifactDir, 'artifacts/task-123/attempt-1');
  assert.equal(allowedBranch(contract), 'agent/task-123/attempt-1');
});

test('qa defaults to a qa report and never gets a branch', () => {
  const contract = parseRunnerContract(QA);
  assert.equal(contract.submissionTarget, 'qa_report');
  assert.equal(contract.baseRef, null);
  assert.equal(contract.targetRevision, 'deadbeef');
  assert.equal(allowedBranch(contract), null);
});

test('a qa task may not be dispatched at a pull request', () => {
  failsWith({ ...QA, AGENT_SUBMISSION_TARGET: 'pull_request' }, 'runner/invalid_submission_target');
});

test('merge authority is only grantable on implementation tasks', () => {
  failsWith({ ...QA, AGENT_MERGE_AUTHORITY: 'merge' }, 'runner/invalid_authority');
  assert.equal(parseRunnerContract({ ...IMPLEMENTATION, AGENT_MERGE_AUTHORITY: 'merge' }).mergeAuthority, 'merge');
});

test('missing task identity, machine identity, and target revision are runner failures', () => {
  failsWith({ ...IMPLEMENTATION, AGENT_TASK_ID: '' }, 'runner/missing_task_identity');
  failsWith({ ...IMPLEMENTATION, INFISICAL_TOKEN: undefined }, 'runner/missing_identity');
  failsWith({ ...QA, AGENT_TARGET_REVISION: '' }, 'runner/missing_target_revision');
  const error = failsWith({ ...IMPLEMENTATION, INFISICAL_API_URL: 'http://secrets.example.com' }, 'runner/invalid_identity');
  assert.equal(error.owner, 'runner');
  assert.equal(error.exitCode, 2);
});

test('identifiers that would escape the artifact directory are rejected', () => {
  failsWith({ ...IMPLEMENTATION, AGENT_TASK_ID: '../../etc' }, 'runner/missing_task_identity');
  failsWith({ ...IMPLEMENTATION, AGENT_ATTEMPT_ID: 'a/b' }, 'runner/missing_task_identity');
});

test('no failure context or contract field carries a secret value', () => {
  const error = failsWith({ ...IMPLEMENTATION, INFISICAL_API_URL: 'not-a-url' }, 'runner/invalid_identity');
  const serialised = JSON.stringify(error.toJSON());
  assert.ok(!serialised.includes(IDENTITY.INFISICAL_TOKEN));

  const contract = parseRunnerContract(IMPLEMENTATION);
  assert.ok(!JSON.stringify(contract).includes(IDENTITY.INFISICAL_TOKEN));
  assert.equal(contract.identity.tokenPresent, true);
});

test('secret value collection covers token-shaped names and spares the non-secret ones', () => {
  const values = secretValues({ ...IDENTITY, SOME_API_KEY: 'abcdefghij', SHORT_TOKEN: 'abc' });
  assert.ok(values.includes(IDENTITY.INFISICAL_TOKEN));
  assert.ok(values.includes('abcdefghij'));
  assert.ok(!values.includes(IDENTITY.INFISICAL_API_URL));
  assert.ok(!values.includes(IDENTITY.INFISICAL_PROJECT_ID));
  assert.ok(!values.includes('abc'), 'values too short to be secrets would cause false positives');
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { mkdtempSync, rmSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import {
  currentOwnership,
  normaliseEntry,
  readLedger,
  recordResource,
  releasable,
  releaseEntry,
  verifyAbsent,
} from '../scripts/lifecycle/resources.mjs';

function ledger() {
  const dir = mkdtempSync(join(tmpdir(), 'ledger-'));
  test.after?.(() => rmSync(dir, { recursive: true, force: true }));
  return join(dir, 'owned-resources.jsonl');
}

test('a recorded resource round-trips through the ledger', () => {
  const path = ledger();
  recordResource(path, { kind: 'process_group', id: '4321', pgid: 4321, label: 'dev-server', scope: 'verify' });
  const entries = readLedger(path);
  assert.equal(entries.length, 1);
  assert.equal(entries[0].kind, 'process_group');
  assert.equal(entries[0].released_at, null);
  assert.ok(entries[0].acquired_at);
});

test('release supersedes acquisition, so teardown is idempotent', () => {
  const path = ledger();
  recordResource(path, { kind: 'process', id: '11', scope: 'verify' });
  assert.equal(releasable(readLedger(path)).length, 1);
  recordResource(path, { kind: 'process', id: '11', scope: 'verify', released_at: new Date().toISOString() });
  assert.equal(releasable(readLedger(path)).length, 0);
  assert.equal(currentOwnership(readLedger(path)).length, 1);
});

test('pre-existing resources are never releasable', () => {
  const path = ledger();
  recordResource(path, { kind: 'container', id: 'abc123' });
  const preexisting = [{ kind: 'container', id: 'abc123' }];
  assert.equal(releasable(readLedger(path), { preexisting }).length, 0);
  assert.equal(releasable(readLedger(path), { preexisting: [] }).length, 1);
});

test('scope narrows what a stage releases', () => {
  const path = ledger();
  recordResource(path, { kind: 'process', id: '1', scope: 'verify' });
  recordResource(path, { kind: 'process', id: '2', scope: 'attempt' });
  assert.deepEqual(
    releasable(readLedger(path), { scope: 'verify' }).map((entry) => entry.id),
    ['1'],
  );
  assert.equal(releasable(readLedger(path), { scope: 'attempt' }).length, 2);
});

test('kinds without a built-in handler must carry release argv', () => {
  assert.throws(() => normaliseEntry({ kind: 'vm', id: 'builder-1' }), /no built-in handler/);
  const entry = normaliseEntry({ kind: 'vm', id: 'builder-1', release: ['true'], verify: ['true'] });
  assert.deepEqual(entry.release, ['true']);
});

test('an unknown kind or a missing id is rejected rather than guessed', () => {
  assert.throws(() => normaliseEntry({ kind: 'kubernetes_pod', id: 'x' }), /unknown resource kind/);
  assert.throws(() => normaliseEntry({ kind: 'process', id: '  ' }), /exact resource id/);
});

test('releasing a temp dir the attempt owns verifies absence', () => {
  const dir = mkdtempSync(join(tmpdir(), 'owned-'));
  const entry = normaliseEntry({ kind: 'temp_dir', id: dir, scope: 'verify' });
  assert.equal(verifyAbsent(entry), false);
  const result = releaseEntry(entry);
  assert.equal(result.absent, true);
  assert.ok(result.released_at);
  assert.equal(existsSync(dir), false);
});

test('an already-gone process reports released rather than failing', () => {
  // A pid this attempt recorded that has since exited must not block teardown.
  const entry = normaliseEntry({ kind: 'process', id: '2147483646', scope: 'verify' });
  const result = releaseEntry(entry);
  assert.equal(result.absent, true);
});

