/**
 * Artifact directory layout, evidence description, and the machine-readable
 * manifest an orchestrator reconciles against.
 */

import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, resolve, sep } from 'node:path';
import { spawnSync } from 'node:child_process';
import { arch, platform, release } from 'node:os';

import { LifecycleError } from './failure.mjs';

export const MANIFEST_SCHEMA = 'agent-artifact-manifest/1';
export const SCENARIOS_SCHEMA = 'agent-qa-scenarios/1';
export const SCENARIO_RESULTS = ['passed', 'failed', 'blocked', 'skipped'];

const TEXT_FORMATS = new Map([
  ['.log', 'text/plain'],
  ['.txt', 'text/plain'],
  ['.md', 'text/markdown'],
  ['.json', 'application/json'],
  ['.jsonl', 'application/x-ndjson'],
  ['.har', 'application/json'],
  ['.csv', 'text/csv'],
  ['.xml', 'text/xml'],
]);

const BINARY_FORMATS = new Map([
  ['.png', 'image/png'],
  ['.jpg', 'image/jpeg'],
  ['.jpeg', 'image/jpeg'],
  ['.webp', 'image/webp'],
  ['.gif', 'image/gif'],
  ['.mp4', 'video/mp4'],
  ['.webm', 'video/webm'],
  ['.mov', 'video/quicktime'],
  ['.zip', 'application/zip'],
]);

export function artifactPaths(contract, repoRoot) {
  const root = resolve(repoRoot, contract.artifactDir);
  if (!root.startsWith(resolve(repoRoot) + sep)) {
    throw new LifecycleError('repo/contract_violation', 'artifact directory escaped the workspace', {
      artifact_dir: contract.artifactDir,
    });
  }
  return {
    root,
    logs: join(root, 'logs'),
    evidence: join(root, 'evidence'),
    manifest: join(root, 'manifest.json'),
    scenarios: join(root, 'scenarios.json'),
    ledger: join(root, 'owned-resources.jsonl'),
    snapshot: join(root, 'preexisting-resources.json'),
    teardown: join(root, 'teardown.json'),
    bootstrap: join(root, 'bootstrap.json'),
    doctor: join(root, 'doctor.json'),
  };
}

export function ensureArtifactDirs(paths) {
  for (const dir of [paths.root, paths.logs, paths.evidence]) {
    try {
      mkdirSync(dir, { recursive: true });
    } catch (error) {
      throw new LifecycleError('runner/workspace_not_writable', `cannot create ${relative(process.cwd(), dir)}`, {
        code: error.code,
      });
    }
  }
  return paths;
}

function git(repoRoot, args) {
  const result = spawnSync('git', args, { cwd: repoRoot, encoding: 'utf8', timeout: 15_000 });
  return result.status === 0 ? result.stdout.trim() : null;
}

export function describeRevision(repoRoot, contract) {
  const head = git(repoRoot, ['rev-parse', 'HEAD']);
  const status = git(repoRoot, ['status', '--porcelain']);
  return {
    git_sha: head,
    dirty: status === null ? null : status !== '',
    base_ref: contract.baseRef,
    /** what the evidence is about: HEAD for implementation, the dispatched revision for qa */
    under_test: contract.resultType === 'qa' ? contract.targetRevision : head,
  };
}

export function describeEnvironment(contract, repoRoot) {
  const pkg = JSON.parse(readFileSync(join(repoRoot, 'package.json'), 'utf8'));
  const pnpm = spawnSync('pnpm', ['--version'], { encoding: 'utf8', timeout: 30_000 });
  return {
    name: contract.environmentName,
    runner: contract.runner,
    os: `${platform()} ${release()}`,
    arch: arch(),
    node: process.version,
    package_manager_declared: pkg.packageManager ?? null,
    package_manager_active: pnpm.status === 0 ? `pnpm@${pnpm.stdout.trim()}` : null,
    ci: process.env.CI === 'true' || process.env.CI === '1',
  };
}

export function classifyFormat(path) {
  const dot = path.lastIndexOf('.');
  const ext = dot === -1 ? '' : path.slice(dot).toLowerCase();
  if (TEXT_FORMATS.has(ext)) return { format: TEXT_FORMATS.get(ext), text: true };
  if (BINARY_FORMATS.has(ext)) return { format: BINARY_FORMATS.get(ext), text: false };
  return { format: 'application/octet-stream', text: false };
}

function walk(dir, root = dir) {
  if (!existsSync(dir)) return [];
  const found = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) found.push(...walk(full, root));
    else if (entry.isFile()) found.push(relative(root, full));
  }
  return found;
}

export function hashFile(path) {
  return createHash('sha256').update(readFileSync(path)).digest('hex');
}

/**
 * Scans text artifacts for injected secret values. Reports the artifact path and
 * a count; never the matched value.
 */
export function scanForSecrets(rootDir, relativePaths, secrets) {
  const findings = [];
  let scanned = 0;
  if (secrets.length === 0) return { scanned, findings, policy: 'no-secret-values-in-environment' };
  for (const rel of relativePaths) {
    const { text } = classifyFormat(rel);
    if (!text) continue;
    scanned += 1;
    const content = readFileSync(join(rootDir, rel), 'utf8');
    const matches = secrets.filter((value) => content.includes(value)).length;
    if (matches > 0) findings.push({ path: rel, matched_secret_count: matches });
  }
  return { scanned, findings, policy: 'reject-injected-secret-values' };
}

/**
 * Describes every preserved file under the attempt directory. `producer` and
 * `scenario` come from the scenario file when the evidence is claimed there.
 */
export function describeArtifacts(paths, { producer, scenarioByPath = new Map(), redacted }) {
  const skip = new Set(['manifest.json']);
  return walk(paths.root)
    .filter((rel) => !skip.has(rel))
    .sort()
    .map((rel) => {
      const full = join(paths.root, rel);
      const claim = scenarioByPath.get(rel);
      return {
        path: rel,
        format: classifyFormat(rel).format,
        bytes: statSync(full).size,
        sha256: hashFile(full),
        producer: claim?.producer ?? producer,
        captured_at: claim?.captured_at ?? statSync(full).mtime.toISOString(),
        scenario: claim?.scenario ?? null,
        redacted,
      };
    });
}

/**
 * Validates the qa scenario file. Its evidence paths are relative to the attempt
 * artifact directory and must already exist.
 */
export function readScenarios(paths) {
  if (!existsSync(paths.scenarios)) {
    throw new LifecycleError(
      'repo/evidence_missing',
      `a qa attempt must write ${relative(process.cwd(), paths.scenarios)} describing each scenario it ran`,
      { expected_schema: SCENARIOS_SCHEMA },
    );
  }
  let parsed;
  try {
    parsed = JSON.parse(readFileSync(paths.scenarios, 'utf8'));
  } catch (error) {
    throw new LifecycleError('repo/evidence_invalid', 'scenarios.json is not valid JSON', { detail: error.message });
  }
  if (parsed.schema !== SCENARIOS_SCHEMA) {
    throw new LifecycleError('repo/evidence_invalid', `scenarios.json schema must be ${SCENARIOS_SCHEMA}`, {
      received: parsed.schema ?? null,
    });
  }
  if (!Array.isArray(parsed.scenarios) || parsed.scenarios.length === 0) {
    throw new LifecycleError('repo/evidence_missing', 'scenarios.json declares no scenarios', {});
  }

  const scenarioByPath = new Map();
  for (const [index, scenario] of parsed.scenarios.entries()) {
    const at = `scenarios[${index}]`;
    if (!scenario.id) {
      throw new LifecycleError('repo/evidence_invalid', `${at} needs an id`, {});
    }
    if (!SCENARIO_RESULTS.includes(scenario.result)) {
      throw new LifecycleError('repo/evidence_invalid', `${at}.result must be one of ${SCENARIO_RESULTS.join(', ')}`, {
        scenario: scenario.id,
        received: scenario.result ?? null,
      });
    }
    if (!scenario.producer) {
      throw new LifecycleError('repo/evidence_invalid', `${at}.producer must name what captured the evidence`, {
        scenario: scenario.id,
      });
    }
    if (!Array.isArray(scenario.evidence) || scenario.evidence.length === 0) {
      if (scenario.result === 'skipped') continue;
      throw new LifecycleError('repo/evidence_missing', `${at} records no evidence`, { scenario: scenario.id });
    }
    for (const item of scenario.evidence ?? []) {
      const rel = typeof item === 'string' ? item : item.path;
      if (!rel || rel.startsWith('/') || rel.includes('..')) {
        throw new LifecycleError('repo/evidence_invalid', `${at} evidence paths must be inside the attempt directory`, {
          scenario: scenario.id,
        });
      }
      if (!existsSync(join(paths.root, rel))) {
        throw new LifecycleError('repo/evidence_missing', `${at} references missing evidence ${rel}`, {
          scenario: scenario.id,
        });
      }
      scenarioByPath.set(rel, {
        scenario: scenario.id,
        producer: typeof item === 'string' ? scenario.producer : item.producer ?? scenario.producer,
        captured_at: typeof item === 'string' ? null : item.captured_at ?? null,
      });
    }
  }
  return { declared: parsed, scenarioByPath };
}

export function writeManifest(paths, manifest) {
  writeFileSync(paths.manifest, `${JSON.stringify(manifest, null, 2)}\n`, 'utf8');
  return paths.manifest;
}

export function writeJson(path, value) {
  mkdirSync(join(path, '..'), { recursive: true });
  writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
  return path;
}

#!/usr/bin/env node
/**
 * `pnpm bootstrap` — noninteractive cold start.
 *
 * Validates the runner contract and machine identity, activates the pinned
 * package manager, installs reproducibly, and reports whether a failure belongs
 * to the repository or the runner. Never prompts, never writes a secret to disk,
 * never prints a secret value.
 */

import { existsSync, readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { join } from 'node:path';

import { EXIT, LifecycleError, printEvent, printFailure } from './failure.mjs';
import { IDENTITY_VARS, parseRunnerContract } from './contract.mjs';
import { artifactPaths, ensureArtifactDirs, describeEnvironment, writeJson } from './artifacts.mjs';

const repoRoot = process.cwd();
const REQUIRED_NODE_MAJOR = 22;

function which(command) {
  return spawnSync('/usr/bin/env', ['which', command], { encoding: 'utf8', timeout: 5000 }).status === 0;
}

function requireToolchain() {
  const nodeMajor = Number(process.versions.node.split('.')[0]);
  if (nodeMajor < REQUIRED_NODE_MAJOR) {
    throw new LifecycleError('runner/toolchain_missing', `node >= ${REQUIRED_NODE_MAJOR} is required`, {
      node: process.version,
    });
  }
  for (const command of ['git', 'corepack']) {
    if (!which(command)) {
      throw new LifecycleError('runner/toolchain_missing', `${command} is not on PATH`, { command });
    }
  }
  return { node: process.version, git: true, corepack: true };
}

function activatePackageManager() {
  const pkg = JSON.parse(readFileSync(join(repoRoot, 'package.json'), 'utf8'));
  const pin = pkg.packageManager;
  if (!pin || !pin.startsWith('pnpm@')) {
    throw new LifecycleError('repo/contract_violation', 'package.json must pin packageManager to a pnpm version', {
      package_manager: pin ?? null,
    });
  }
  const prepared = spawnSync('corepack', ['prepare', pin, '--activate'], {
    cwd: repoRoot,
    encoding: 'utf8',
    timeout: 300_000,
  });
  if (prepared.status !== 0) {
    const stderr = prepared.stderr ?? '';
    const offline = /ENOTFOUND|EAI_AGAIN|ETIMEDOUT|network|ECONNREFUSED/i.test(stderr);
    throw new LifecycleError(
      offline ? 'runner/network_denied' : 'runner/toolchain_missing',
      `corepack could not activate ${pin}`,
      { exit_code: prepared.status },
    );
  }
  const active = spawnSync('pnpm', ['--version'], { cwd: repoRoot, encoding: 'utf8', timeout: 60_000 });
  if (active.status !== 0) {
    throw new LifecycleError('runner/toolchain_missing', 'pnpm is not runnable after corepack activation', {
      exit_code: active.status,
    });
  }
  const expected = pin.slice('pnpm@'.length);
  const actual = active.stdout.trim();
  if (actual !== expected) {
    throw new LifecycleError('repo/package_manager_mismatch', 'active pnpm does not match the declared pin', {
      declared: expected,
      active: actual,
    });
  }
  return { declared: pin, active: `pnpm@${actual}` };
}

function installDependencies(logPath) {
  const pkg = JSON.parse(readFileSync(join(repoRoot, 'package.json'), 'utf8'));
  const declared =
    Object.keys(pkg.dependencies ?? {}).length +
    Object.keys(pkg.devDependencies ?? {}).length +
    Object.keys(pkg.optionalDependencies ?? {}).length;

  if (declared === 0) {
    return { performed: false, reason: 'no declared dependencies', declared_dependencies: 0 };
  }
  if (!existsSync(join(repoRoot, 'pnpm-lock.yaml'))) {
    throw new LifecycleError('repo/missing_lockfile', 'declared dependencies require a committed pnpm-lock.yaml', {
      declared_dependencies: declared,
    });
  }
  const installed = spawnSync('pnpm', ['install', '--frozen-lockfile'], {
    cwd: repoRoot,
    encoding: 'utf8',
    timeout: 900_000,
    env: { ...process.env, CI: 'true' },
  });
  writeJson(logPath, {
    command: 'pnpm install --frozen-lockfile',
    exit_code: installed.status,
    stdout_tail: (installed.stdout ?? '').split('\n').slice(-40).join('\n'),
    stderr_tail: (installed.stderr ?? '').split('\n').slice(-40).join('\n'),
  });
  if (installed.status !== 0) {
    const stderr = installed.stderr ?? '';
    if (/ERR_PNPM_OUTDATED_LOCKFILE/.test(stderr)) {
      throw new LifecycleError('repo/missing_lockfile', 'pnpm-lock.yaml is out of date with package.json', {
        declared_dependencies: declared,
      });
    }
    if (/ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNREFUSED|registry/i.test(stderr)) {
      throw new LifecycleError('runner/network_denied', 'the package registry was unreachable', {
        exit_code: installed.status,
      });
    }
    throw new LifecycleError('repo/dependency_install_failed', 'pnpm install failed', {
      exit_code: installed.status,
      log: logPath,
    });
  }
  return { performed: true, declared_dependencies: declared, frozen_lockfile: true };
}

/**
 * Optional liveness check for the injected identity. Off by default so bootstrap
 * stays offline-safe; enable with AGENT_IDENTITY_PROBE=1 when egress is allowed.
 */
async function probeIdentity(contract) {
  if (process.env.AGENT_IDENTITY_PROBE !== '1') {
    return { probed: false, reason: 'AGENT_IDENTITY_PROBE is not 1' };
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 10_000);
  try {
    const response = await fetch(new URL('/api/status', contract.identity.apiUrl), {
      method: 'GET',
      headers: { authorization: `Bearer ${process.env.INFISICAL_TOKEN}` },
      signal: controller.signal,
    });
    if (response.status === 401 || response.status === 403) {
      throw new LifecycleError('runner/missing_identity', 'the injected identity was rejected by the secret manager', {
        http_status: response.status,
      });
    }
    return { probed: true, http_status: response.status };
  } catch (error) {
    if (error instanceof LifecycleError) throw error;
    throw new LifecycleError('runner/network_denied', 'the secret manager endpoint was unreachable', {
      code: error.name,
    });
  } finally {
    clearTimeout(timer);
  }
}

async function main() {
  const startedAt = new Date().toISOString();
  const contract = parseRunnerContract(process.env);
  const paths = ensureArtifactDirs(artifactPaths(contract, repoRoot));

  const toolchain = requireToolchain();
  const packageManager = activatePackageManager();
  const install = installDependencies(join(paths.logs, 'install.json'));
  const identity = await probeIdentity(contract);

  const record = {
    stage: 'bootstrap',
    outcome: 'ready',
    task_id: contract.taskId,
    attempt_id: contract.attemptId,
    attempt_number: contract.attemptNumber,
    result_type: contract.resultType,
    submission_target: contract.submissionTarget,
    merge_authority: contract.mergeAuthority,
    started_at: startedAt,
    finished_at: new Date().toISOString(),
    toolchain,
    package_manager: packageManager,
    install,
    identity: {
      variables_present: IDENTITY_VARS,
      project_id: contract.identity.projectId,
      api_url: contract.identity.apiUrl,
      token_present: true,
      probe: identity,
    },
    environment: describeEnvironment(contract, repoRoot),
  };
  writeJson(paths.bootstrap, record);
  printEvent({
    event: 'lifecycle.bootstrap',
    operation: 'bootstrap',
    resource_id: `${contract.taskId}/${contract.attemptId}`,
    outcome: 'ready',
    error_kind: null,
    install_performed: install.performed,
  });
  return EXIT.ok;
}

main()
  .then((code) => process.exit(code))
  .catch((error) => {
    const failure = printFailure('bootstrap', error);
    printEvent({
      event: 'lifecycle.bootstrap',
      operation: 'bootstrap',
      resource_id: `${process.env.AGENT_TASK_ID ?? 'unknown'}/${process.env.AGENT_ATTEMPT_ID ?? 'unknown'}`,
      outcome: 'failed',
      error_kind: failure.failureClass,
      retryable: failure.retryable,
    });
    process.exit(failure.exitCode);
  });

#!/usr/bin/env node
/**
 * `pnpm doctor` — read-only "is this workspace worth driving?" check.
 *
 * Never installs, repairs, or mutates state. Run it before driving the workspace
 * and again after anything surprising. It names the missing capability and its
 * owner; bootstrap is what fixes things.
 */

import { accessSync, constants, existsSync, readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { dirname, join } from 'node:path';

import { EXIT, FAILURE_CLASSES, LifecycleError, printEvent } from './failure.mjs';
import { IDENTITY_VARS, parseRunnerContract } from './contract.mjs';
import { artifactPaths, writeJson } from './artifacts.mjs';
import { readLedger, readSnapshot, releasable } from './resources.mjs';

const repoRoot = process.cwd();

function check(name, fn) {
  try {
    const detail = fn();
    return { check: name, ok: true, ...detail };
  } catch (error) {
    const failure = error instanceof LifecycleError ? error : null;
    return {
      check: name,
      ok: false,
      failure_class: failure?.failureClass ?? 'internal/unknown',
      owner: failure?.owner ?? 'internal',
      detail: error.message,
      recovery: failure?.recovery ?? FAILURE_CLASSES['internal/unknown'].recovery,
    };
  }
}

function nearestExistingDir(path) {
  let current = path;
  while (!existsSync(current) && dirname(current) !== current) current = dirname(current);
  return current;
}

function toolPresent(command) {
  return spawnSync('/usr/bin/env', ['which', command], { encoding: 'utf8', timeout: 5000 }).status === 0;
}

function main() {
  let contract = null;
  const results = [];

  results.push(
    check('runner_contract', () => {
      contract = parseRunnerContract(process.env);
      return {
        task_id: contract.taskId,
        attempt_id: contract.attemptId,
        result_type: contract.resultType,
        submission_target: contract.submissionTarget,
        merge_authority: contract.mergeAuthority,
      };
    }),
  );

  results.push(
    check('machine_identity', () => {
      const missing = IDENTITY_VARS.filter((name) => !process.env[name]?.trim());
      if (missing.length > 0) {
        throw new LifecycleError('runner/missing_identity', `missing: ${missing.join(', ')}`, { missing });
      }
      return { variables_present: IDENTITY_VARS, values_read: false };
    }),
  );

  results.push(
    check('toolchain', () => {
      const missing = ['git', 'corepack', 'pnpm'].filter((command) => !toolPresent(command));
      if (missing.length > 0) {
        throw new LifecycleError('runner/toolchain_missing', `missing: ${missing.join(', ')}`, { missing });
      }
      const pkg = JSON.parse(readFileSync(join(repoRoot, 'package.json'), 'utf8'));
      const active = spawnSync('pnpm', ['--version'], { encoding: 'utf8', timeout: 60_000 });
      const activePin = active.status === 0 ? `pnpm@${active.stdout.trim()}` : null;
      if (activePin !== pkg.packageManager) {
        throw new LifecycleError('repo/package_manager_mismatch', 'run bootstrap to activate the pinned pnpm', {
          declared: pkg.packageManager ?? null,
          active: activePin,
        });
      }
      return { node: process.version, package_manager: activePin };
    }),
  );

  results.push(
    check('dependencies_installed', () => {
      const pkg = JSON.parse(readFileSync(join(repoRoot, 'package.json'), 'utf8'));
      const declared =
        Object.keys(pkg.dependencies ?? {}).length + Object.keys(pkg.devDependencies ?? {}).length;
      if (declared === 0) return { declared_dependencies: 0, node_modules: false };
      if (!existsSync(join(repoRoot, 'node_modules'))) {
        throw new LifecycleError('repo/dependency_install_failed', 'node_modules is absent; run bootstrap', {
          declared_dependencies: declared,
        });
      }
      return { declared_dependencies: declared, node_modules: true };
    }),
  );

  results.push(
    check('revision_under_test', () => {
      const head = spawnSync('git', ['rev-parse', 'HEAD'], { cwd: repoRoot, encoding: 'utf8', timeout: 15_000 });
      if (head.status !== 0) {
        throw new LifecycleError('runner/workspace_not_writable', 'the workspace is not a resolvable git checkout', {});
      }
      if (contract?.resultType === 'qa') {
        const target = spawnSync('git', ['cat-file', '-e', `${contract.targetRevision}^{commit}`], {
          cwd: repoRoot,
          encoding: 'utf8',
          timeout: 15_000,
        });
        if (target.status !== 0) {
          throw new LifecycleError(
            'runner/missing_target_revision',
            'AGENT_TARGET_REVISION is not present in this checkout',
            { target_revision: contract.targetRevision },
          );
        }
      }
      return { head: head.stdout.trim(), target_revision: contract?.targetRevision ?? null };
    }),
  );

  results.push(
    check('artifact_workspace', () => {
      if (!contract) throw new LifecycleError('runner/missing_task_identity', 'no contract to resolve paths from', {});
      const paths = artifactPaths(contract, repoRoot);
      const anchor = nearestExistingDir(paths.root);
      try {
        accessSync(anchor, constants.W_OK);
      } catch {
        throw new LifecycleError('runner/workspace_not_writable', `${anchor} is not writable`, {});
      }
      return { artifact_dir: contract.artifactDir, writable_anchor: anchor };
    }),
  );

  results.push(
    check('bootstrapped_for_this_attempt', () => {
      if (!contract) throw new LifecycleError('runner/missing_task_identity', 'no contract', {});
      const paths = artifactPaths(contract, repoRoot);
      if (!existsSync(paths.bootstrap)) {
        throw new LifecycleError('repo/contract_violation', 'bootstrap has not run for this attempt', {
          expected: paths.bootstrap,
        });
      }
      const record = JSON.parse(readFileSync(paths.bootstrap, 'utf8'));
      if (record.task_id !== contract.taskId || record.attempt_id !== contract.attemptId) {
        throw new LifecycleError('repo/contract_violation', 'the bootstrap record belongs to another attempt', {
          recorded: `${record.task_id}/${record.attempt_id}`,
        });
      }
      return { bootstrapped_at: record.finished_at, install_performed: record.install?.performed ?? null };
    }),
  );

  results.push(
    check('no_leaked_owned_resources', () => {
      if (!contract) throw new LifecycleError('runner/missing_task_identity', 'no contract', {});
      const paths = artifactPaths(contract, repoRoot);
      const outstanding = releasable(readLedger(paths.ledger), {
        preexisting: readSnapshot(paths.snapshot).items,
      });
      if (outstanding.length > 0) {
        throw new LifecycleError(
          'repo/teardown_failed',
          `${outstanding.length} owned resource(s) from an earlier run are still held; run pnpm teardown`,
          { outstanding: outstanding.map((entry) => `${entry.kind}:${entry.id}`) },
        );
      }
      return { outstanding: 0 };
    }),
  );

  const failed = results.filter((result) => !result.ok);
  const report = {
    stage: 'doctor',
    checked_at: new Date().toISOString(),
    outcome: failed.length === 0 ? 'healthy' : 'unhealthy',
    checks: results,
    first_gap: failed[0] ? { check: failed[0].check, failure_class: failed[0].failure_class } : null,
  };

  if (contract) {
    const paths = artifactPaths(contract, repoRoot);
    if (existsSync(paths.root)) writeJson(paths.doctor, report);
  }
  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
  printEvent({
    event: 'lifecycle.doctor',
    operation: 'doctor',
    resource_id: contract ? `${contract.taskId}/${contract.attemptId}` : 'unknown',
    outcome: report.outcome,
    error_kind: report.first_gap?.failure_class ?? null,
  });

  if (failed.length === 0) return EXIT.ok;
  return failed.some((result) => result.owner === 'runner') ? EXIT.runner : EXIT.repository;
}

process.exit(main());

#!/usr/bin/env node
/**
 * `pnpm teardown` — idempotent release of resources this attempt raised.
 *
 * Safe on success, failure, cancellation, timeout, and retry. It releases only
 * ledger entries recorded by the attempt, preserves everything in the
 * pre-existing snapshot, verifies absence rather than trusting exit status, and
 * never deletes captured evidence.
 *
 * Also importable: verify.mjs calls runTeardown() on every exit path.
 */

import { existsSync, readFileSync } from 'node:fs';

import { EXIT, LifecycleError, printEvent, printFailure } from './failure.mjs';
import { parseRunnerContract } from './contract.mjs';
import { artifactPaths, writeJson } from './artifacts.mjs';
import { readLedger, readSnapshot, recordResource, releasable, releaseEntry, verifyPreservation } from './resources.mjs';

export const TEARDOWN_REASONS = ['success', 'failure', 'cancelled', 'timeout', 'retry'];

/**
 * @param {object} options
 * @param {'bootstrap'|'verify'|'attempt'} options.scope which stage's resources to release
 * @param {string} options.reason why teardown ran, for the record
 * @param {number} options.primaryStatus exit status of the work that preceded teardown
 */
export function runTeardown({ contract, paths, scope = 'attempt', reason = 'success', primaryStatus = 0 }) {
  const startedAt = new Date().toISOString();
  const snapshot = readSnapshot(paths.snapshot);
  const outstanding = releasable(readLedger(paths.ledger), { scope, preexisting: snapshot.items });

  const releases = outstanding.map((entry) => releaseEntry(entry));
  for (const [index, result] of releases.entries()) {
    if (result.absent) {
      recordResource(paths.ledger, { ...outstanding[index], released_at: result.released_at });
    }
  }

  const survivors = releases.filter((result) => !result.absent);
  const preservationViolations = verifyPreservation(snapshot);
  const clean = survivors.length === 0 && preservationViolations.length === 0;

  const history = existsSync(paths.teardown) ? JSON.parse(readFileSync(paths.teardown, 'utf8')).runs ?? [] : [];
  const record = {
    stage: 'teardown',
    task_id: contract.taskId,
    attempt_id: contract.attemptId,
    runs: [
      ...history,
      {
        scope,
        reason,
        primary_status: primaryStatus,
        started_at: startedAt,
        finished_at: new Date().toISOString(),
        outcome: clean ? 'clean' : 'incomplete',
        released: releases.filter((result) => result.absent).map(({ kind, id, label, note }) => ({ kind, id, label, note })),
        survivors,
        preserved_pre_existing: snapshot.items.length,
        preservation_violations: preservationViolations,
      },
    ],
  };
  writeJson(paths.teardown, record);

  const failureClass = clean ? null : 'repo/teardown_failed';
  printEvent({
    event: 'lifecycle.teardown',
    operation: 'teardown',
    resource_id: `${contract.taskId}/${contract.attemptId}`,
    outcome: clean ? 'clean' : 'incomplete',
    error_kind: failureClass,
    scope,
    reason,
    released: releases.filter((result) => result.absent).length,
    survivors: survivors.length,
  });

  // Preserve a primary failure or signal status; report cleanup separately.
  // If the primary work succeeded, an incomplete cleanup makes the command fail.
  let exitCode = primaryStatus;
  if (!clean && primaryStatus === 0) exitCode = EXIT.teardown;

  return { clean, exitCode, record, survivors, preservationViolations };
}

function parseArgs(argv) {
  const options = { scope: 'attempt', reason: 'success', primaryStatus: 0 };
  for (let index = 0; index < argv.length; index += 1) {
    const [flag, inline] = argv[index].split('=');
    const value = inline ?? argv[index + 1];
    if (inline === undefined && value !== undefined) index += 1;
    if (flag === '--scope') options.scope = value;
    else if (flag === '--reason') options.reason = value;
    else if (flag === '--primary-status') options.primaryStatus = Number(value);
    else throw new LifecycleError('repo/contract_violation', `unknown teardown flag: ${flag}`, {});
  }
  if (!TEARDOWN_REASONS.includes(options.reason)) {
    throw new LifecycleError('repo/contract_violation', `--reason must be one of ${TEARDOWN_REASONS.join(', ')}`, {
      received: options.reason,
    });
  }
  if (!Number.isInteger(options.primaryStatus) || options.primaryStatus < 0) {
    throw new LifecycleError('repo/contract_violation', '--primary-status must be a non-negative integer', {});
  }
  return options;
}

function main() {
  const options = parseArgs(process.argv.slice(2));
  const contract = parseRunnerContract(process.env);
  const paths = artifactPaths(contract, process.cwd());
  const result = runTeardown({ contract, paths, ...options });
  if (!result.clean) {
    printFailure(
      'teardown',
      new LifecycleError('repo/teardown_failed', 'owned resources survived teardown or a preserved resource vanished', {
        survivors: result.survivors.map((item) => `${item.kind}:${item.id}`),
        preservation_violations: result.preservationViolations.map((item) => `${item.kind}:${item.id}`),
        record: paths.teardown,
      }),
    );
  }
  return result.exitCode;
}

// Only run as a CLI, so verify.mjs can import runTeardown without side effects.
if (process.argv[1] && process.argv[1].endsWith('teardown.mjs')) {
  try {
    process.exit(main());
  } catch (error) {
    const failure = printFailure('teardown', error);
    process.exit(failure.exitCode);
  }
}

